请对以下 case 进行三维加权评分。

=== case_id ===
Case-26-group-buy-006

=== 用户原始指令 (query.txt) ===
拼单成功那个按钮,点一下能跳到app里就行

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "拼单成功那个按钮,点一下能跳到app里就行",
  "size": "2x2",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "com.example.groupbuy",
        "abilityName": "EntryAbility",
        "uri": "groupbuy://order/success"
      }
    }
  ],
  "dataModelSchema": {
    "data": {
      "groupBuy": {
        "title": {
          "type": "string",
          "description": "拼单团购服务标题",
          "sampleValue": "邻里拼单"
        },
        "statusText": {
          "type": "string",
          "description": "拼单当前结果状态",
          "sampleValue": "拼单成功"
        },
        "summary": {
          "type": "string",
          "description": "拼单成功后的摘要说明",
          "sampleValue": "2人成团 已锁价"
        },
        "actionText": {
          "type": "string",
          "description": "跳转到应用继续查看的动作短文案",
          "sampleValue": "去App查看"
        }
      }
    }
  },
  "assetCandidates": []
}

